# Function to count valid pairs for Case 1
def count_case1_pairs(max_value):
    count = 0
    for x in range(1, max_value + 1):
        if x % 4 == 0:
            for y in range(x + 1, max_value + 1):
                if y % 4 == 0:
                    count += 1
    return count

# Function to count valid pairs for Case 2
def count_case2_pairs(max_value):
    count = 0
    # For i^x = i and i^y = -i
    for x in range(1, max_value + 1):
        if x % 4 == 1:
            for y in range(x + 1, max_value + 1):
                if y % 4 == 3:
                    count += 1

    # For i^x = -i and i^y = i
    for x in range(1, max_value + 1):
        if x % 4 == 3:
            for y in range(x + 1, max_value + 1):
                if y % 4 == 1:
                    count += 1
    return count

# Maximum value
max_value = 100

# Count pairs for Case 1
case1_count = count_case1_pairs(max_value)

# Count pairs for Case 2
case2_count = count_case2_pairs(max_value)

# Total count of valid pairs
total_count = case1_count + case2_count

print("Final Answer:", total_count)
